{
  "World_Name": "Veridia (Placeholder)",
  "Overall_Style": "A grounded, low-magic Western-fantasy setting with a focus on realistic world-building and pronounced racial differences.",
  "Regions": {
    "Southern_Kingdom": {
      "Primary_Inhabitants": "Humans",
      "Geography_and_Climate": "The primary story setting, located on a southern continent with a temperate climate and a fragmented, complex coastline.",
      "Government": "An ancient human kingdom with a political system based on feudalism, but with a more centralized royal authority."
    },
    "Central_Corridor": {
      "Primary_Inhabitants": "Humans and Native Peoples",
      "Geography_and_Climate": "A hot, arid desert region with a cultural aesthetic based on real-world North African and Arabian cultures.",
      "Political_Status": "Formerly independent, this land and its dark-skinned native population have been conquered and incorporated into the Southern Kingdom."
    },
    "Northern_Treesea": {
      "Primary_Inhabitants": "Elves",
      "History": "Formerly spanning a much larger territory, the elves have been pushed back by humans over centuries of war, resulting in massive territorial loss and a sharp decline in the male population.",
      "Current_Affairs": "Led by their Queen, the elves have begun a major counter-offensive. The war has now escalated and spread into the Central Corridor.",
      "Unique_Biology": "Through a combination of magic and alchemy (秘药), female elves have developed the ability to reproduce amongst themselves, slowly rebuilding their numbers for the current war effort."
    }
  }
}

